type forth struct {
	stack []int
	words map[string]func(*forth) error
}

func (f *forth) binop(op func(a, b int) (int, error)) func(*forth) error {
	return func(f *forth) error {
		if len(f.stack) < 2 {
			return errors.New("only one value on the stack")
		}
		b := f.stack[len(f.stack)-1]
		a := f.stack[len(f.stack)-2]
		r, err := op(a, b)
		if err != nil {
			return err
		}
		f.stack = append(f.stack[:len(f.stack)-2], r)
		return nil
	}
}

func (f *forth) unop(op func(a int) (int, error)) func(*forth) error {
	return func(f *forth) error {
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		a := f.stack[len(f.stack)-1]
		r, err := op(a)
		if err != nil {
			return err
		}
		f.stack[len(f.stack)-1] = r
		return nil
	}
}
