	f.words["-"] = f.binop(func(a, b int) (int, error) { return a - b, nil })
	f.words["*"] = f.binop(func(a, b int) (int, error) { return a * b, nil })
	f.words["/"] = f.binop(func(a, b int) (int, error) {
