		return a / b, nil
	})
	f.words["dup"] = f.unop(func(a int) (int, error) { return a, nil })
	f.words["drop"] = func(f *forth) error {
		if len(f.stack) < 1 { return errors.New("empty stack") }
		f.stack = f.stack[:len(f.stack)-1]
		return nil
	}
	f.words["swap"] = func(f *forth) error {
		if len(f.stack) < 2 { return errors.New("only one value on the stack") }
		n := len(f.stack)
		f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
		return nil
