package forth

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

type forth struct {
	stack []int
	words map[string]func(*forth) error
}

func newForth() *forth {
	f := &forth{
		stack: []int{},
		words: map[string]func(*forth) error{},
	}

	f.words["+"] = f.binop(func(a, b int) (int, error) { return a + b, nil })
	f.words["-"] = f.binop(func(a, b int) (int, error) { return a - b, nil })
	f.words["*"] = f.binop(func(a, b int) (int, error) { return a * b, nil })
	f.words["/"] = f.binop(func(a, b int) (int, error) {
		if b == 0 {
			return 0, errors.New("division by zero")
		}
		return a / b, nil
	})
	f.words["dup"] = f.unop(func(a int) (int, error) { return a, nil })
	f.words["drop"] = func(f *forth) error {
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		f.stack = f.stack[:len(f.stack)-1]
		return nil
	}
	f.words["swap"] = func(f *forth) error {
		if len(f.stack) < 2 {
			return errors.New("only one value on the stack")
		}
		n := len(f.stack)
		f.stack[n-1], f.stack[n-2] = f.stack[n-2], f.stack[n-1]
		return nil
	}
	f.words["over"] = func(f *forth) error {
		if len(f.stack) < 2 {
			return errors.New("only one value on the stack")
		}
		f.stack = append(f.stack, f.stack[len(f.stack)-2])
		return nil
	}
	return f
}

func (f *forth) binop(op func(a, b int) (int, error)) func(*forth) error {
	return func(f *forth) error {
		if len(f.stack) < 2 {
			if len(f.stack) < 1 {
				return errors.New("empty stack")
			}
			return errors.New("only one value on the stack")
		}
		b := f.stack[len(f.stack)-1]
		a := f.stack[len(f.stack)-2]
		r, err := op(a, b)
		if err != nil {
			return err
		}
		f.stack = append(f.stack[:len(f.stack)-2], r)
		return nil
	}
}

func (f *forth) unop(op func(a int) (int, error)) func(*forth) error {
	return func(f *forth) error {
		if len(f.stack) < 1 {
			return errors.New("empty stack")
		}
		a := f.stack[len(f.stack)-1]
		r, err := op(a)
		if err != nil {
			return err
		}
		f.stack[len(f.stack)-1] = r
		return nil
	}
}

func isNumber(s string) bool {
	_, err := strconv.Atoi(s)
	return err == nil
}

// resolve looks up a token as an operation, resolving user-defined words
// first so that definitions capture the words as they were at definition
// time (local scope).
func (f *forth) resolve(tok string) (func(*forth) error, error) {
	if n, err := strconv.Atoi(tok); err == nil {
		return func(f *forth) error {
			f.stack = append(f.stack, n)
			return nil
		}, nil
	}
	op, ok := f.words[tok]
	if !ok {
		return nil, fmt.Errorf("undefined operation: %s", tok)
	}
	return op, nil
}

func (f *forth) evalLine(line string) error {
	tokens := strings.Fields(line)
	for i := 0; i < len(tokens); i++ {
		tok := strings.ToLower(tokens[i])
		if tok != ":" {
			if _, err := f.resolve(tok); err != nil {
				return err
			}
			if err := f.exec(tok); err != nil {
				return err
			}
			continue
		}
		// Definition: : name body... ;
		if i+1 >= len(tokens) {
			return errors.New("missing word name in definition")
		}
		name := strings.ToLower(tokens[i+1])
		if isNumber(name) {
			return errors.New("cannot redefine a number")
		}
		body := []func(*forth) error{}
		j := i + 2
		for j < len(tokens) && strings.ToLower(tokens[j]) != ";" {
			op, err := f.resolve(tokens[j])
			if err != nil {
				return err
			}
			body = append(body, op)
			j++
		}
		if j >= len(tokens) {
			return errors.New("missing ; in definition")
		}
		f.words[name] = func(f *forth) error {
			for _, op := range body {
				if err := op(f); err != nil {
					return err
				}
			}
			return nil
		}
		i = j
	}
	return nil
}

func (f *forth) exec(tok string) error {
	if n, err := strconv.Atoi(tok); err == nil {
		f.stack = append(f.stack, n)
		return nil
	}
	op, ok := f.words[tok]
	if !ok {
		return fmt.Errorf("undefined operation: %s", tok)
	}
	return op(f)
}

// Forth evaluates a program given as a slice of lines and returns the
// final stack.
func Forth(input []string) ([]int, error) {
	f := newForth()
	for _, line := range input {
		if err := f.evalLine(line); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

